/* ---------------------------------------------------------
   ---------- HELPER FUNCTIONS
   --------------------------------------------------------- */

function isTextFile(name) {
  return name.match(/\.(txt|py|cpp|c|cs|java|js|ts|json|xml|html|css|md|yml|yaml|patch)$/i);
}
function isImage(name) {
  return name.match(/\.(png|jpg|jpeg|gif)$/i);
}
function isPdf(name) {
  return name.toLowerCase().endsWith(".pdf");
}
function detectLanguage(filename) {
  const ext = filename.split(".").pop().toLowerCase();
  const map = {
    txt: "markup",
    py: "python",
    cpp: "cpp",
    c: "c",
    cs: "csharp",
    java: "java",
    js: "javascript",
    ts: "typescript",
    json: "json",
    xml: "xml",
    html: "html",
    css: "css",
    md: "markdown",
    yml: "yaml",
    yaml: "yaml"
  };
  return map[ext] || "markup";
}
