import React, { useEffect, useState, useRef } from "react";
import { useNavigate, useParams } from "react-router-dom";
import "prismjs/themes/prism-okaidia.css";
import Prism from "prismjs";
import "prismjs/components/prism-python";
import "prismjs/components/prism-c";
import "prismjs/components/prism-cpp";
import "prismjs/components/prism-java";
import "prismjs/components/prism-json";
import "prismjs/components/prism-markdown";
import "prismjs/components/prism-yaml";
import "prismjs/components/prism-javascript";
import "prismjs/components/prism-typescript";
import "prismjs/components/prism-css";
import "./App.css";
import ParticipantNavbar from "./components/ParticipantNavbar";
import { Star } from "lucide-react";

function TaskDetailPage() {
    const { taskId } = useParams();
    const [selectedArtifacts, setSelectedArtifacts] = useState([]);
    const storedUser = JSON.parse(localStorage.getItem("user"));
    const username = storedUser?.username || "Participant";

    const [task, setTask] = useState(null);
    const [loading, setLoading] = useState(true);
    const [textContents, setTextContents] = useState({});
    const [hover, setHover] = useState(null);
    const [selectedCard, setSelectedCard] = useState(null);
    const [activeAction, setActiveAction] = useState(null);
    const [activeArtifact, setActiveArtifact] = useState(null);
    const [compareHover, setCompareHover] = useState(null);

    const fieldCodes = ["A1", "A2", "A3", "A4"];

    const [commentsByField, setCommentsByField] = useState({});
    const [newCommentText, setNewCommentText] = useState("");
    const [imageUrls, setImageUrls] = useState({});
    const [pdfUrls, setPdfUrls] = useState({});

    const gridRef = useRef(null);

    // 🔥 REPORT STATE
    const [reportContext, setReportContext] = useState(null);
    // { targetType: "ARTIFACT" | "PARTICIPANT", artifact, reportedUsername? }
    const [reportReason, setReportReason] = useState("");
    const [reportDescription, setReportDescription] = useState("");
    const [reportSubmitting, setReportSubmitting] = useState(false);
    const [reportError, setReportError] = useState("");
    const [reportSuccess, setReportSuccess] = useState("");

    //reply comment
    const [replyTarget, setReplyTarget] = useState(null);
    const [replyText, setReplyText] = useState("");
    const [openReplies, setOpenReplies] = useState({});

    //edit or delete comment
    const [editingCommentId, setEditingCommentId] = useState(null);
    const [editText, setEditText] = useState("");

    //evaluation
    const [evaluationAnswers, setEvaluationAnswers] = useState({});

    //custom criterias
    const [customCriteria, setCustomCriteria] = useState({});

    //new evaluation format
    const [answers, setAnswers] = useState({});

    const handleSubmit = async () => {
        if (!task) return;

        const token = localStorage.getItem("token");

        const orderedAnswers = task.evaluationCriteria
            .slice()
            .sort((a, b) => a.priorityOrder - b.priorityOrder)
            .map(c => answers[c.id] ?? "");

        const payload = {
            taskId: task.id,
            answers: orderedAnswers
        };

        try {
            const res = await fetch("http://localhost:8080/api/participant/submit-response", {
                method: "POST",
                headers: {
                    "Content-Type": "application/json",
                    Authorization: `Bearer ${token}`,
                },
                body: JSON.stringify(payload)
            });

            if (!res.ok) throw new Error("Submit failed");

            alert("Submit successful!");
        } catch (err) {
            console.error(err);
            alert("Submit error");
        }
    };

    const getFileIcon = (filename) => {
        const ext = filename.split(".").pop().toLowerCase();

        switch (ext) {
            case "java":
                return "☕";
            case "cpp":
                return "⚙️";
            case "py":
                return "🐍";
            case "js":
                return "📜";
            case "ts":
                return "🟦";
            case "pdf":
                return "📕";
            case "txt":
                return "📄";
            default:
                return "📄";
        }
    };

    const getFileColor = (filename) => {
        const ext = filename.split(".").pop().toLowerCase();

        switch (ext) {
            case "java":
                return { bg: "rgba(244,114,182,0.15)", color: "#f472b6" };
            case "cpp":
                return { bg: "rgba(96,165,250,0.15)", color: "#60a5fa" };
            case "py":
                return { bg: "rgba(250,204,21,0.15)", color: "#fde047" };
            case "js":
                return { bg: "rgba(34,197,94,0.15)", color: "#4ade80" };
            case "ts":
                return { bg: "rgba(96,165,250,0.15)", color: "#3b82f6" };
            case "pdf":
                return { bg: "rgba(239,68,68,0.15)", color: "#f87171" };
            case "txt":
                return { bg: "rgba(156,163,175,0.15)", color: "#9ca3af" };
            default:
                return { bg: "rgba(156,163,175,0.15)", color: "#9ca3af" };
        }
    };

    // --------------------------
    // SCROLL TO CARD FUNC
    // --------------------------
    const scrollToIndex = (i) => {
        if (!gridRef.current) return;

        const grid = gridRef.current;
        const card = grid.children[i];

        const cardWidth = card.offsetWidth;
        const gridWidth = grid.offsetWidth;

        const target = card.offsetLeft - gridWidth / 2 + cardWidth / 2;

        grid.scrollTo({
            left: target,
            behavior: "smooth",
        });
    };

    const toggleSelect = (id) => {
        setSelectedArtifacts((prev) => {
            if (prev.includes(id)) {
                return prev.filter((x) => x !== id);
            }
            if (prev.length >= 3) return prev;
            return [...prev, id];
        });
    };

    // COMMENT SECTION
    const submitComment = (fieldCode) => {
        const text = newCommentText[fieldCode];
        if (!text || !text.trim()) return;

        const token = localStorage.getItem("token");

        fetch("http://localhost:8080/api/comments", {
            method: "POST",
            headers: {
                "Content-Type": "application/json",
                Authorization: `Bearer ${token}`,
            },
            body: JSON.stringify({
                taskId: Number(taskId),
                fieldCode: fieldCode,
                content: text,
                parentCommentId: null,
            }),
        })
            .then((res) => res.json())
            .then((saved) => {
                setCommentsByField((prev) => ({
                    ...prev,
                    [fieldCode]: [...(prev[fieldCode] || []), saved],
                }));

                // sadece o field’ın textarea’sını temizle
                setNewCommentText((p) => ({ ...p, [fieldCode]: "" }));
            })
            .catch((err) => console.error(err));
    };

    const likeComment = (commentId, fieldCode) => {
        const token = localStorage.getItem("token");

        fetch(`http://localhost:8080/api/comments/${commentId}/like`, {
            method: "POST",
            headers: {
                Authorization: `Bearer ${token}`,
            },
        })
            .then((res) => res.json())
            .then((updated) => {
                setCommentsByField((prev) => ({
                    ...prev,
                    [fieldCode]: (prev[fieldCode] || []).map((c) =>
                        c.id === commentId ? updated : c
                    ),
                }));
            })
            .catch((err) => console.error("Like error:", err));
    };

    const deleteComment = async (commentId, fieldCode) => {
        const token = localStorage.getItem("token");

        const res = await fetch(`http://localhost:8080/api/comments/${commentId}`, {
            method: "DELETE",
            headers: {
                Authorization: `Bearer ${token}`
            }
        });

        if (!res.ok) {
            alert("Delete failed.");
            return;
        }

        // UI'dan kaldır
        setCommentsByField(prev => ({
            ...prev,
            [fieldCode]: prev[fieldCode].map(c =>
                c.id === commentId ? { ...c, deleted: true, content: "deleted" } : c
            )
        }));
    };

    const editComment = async (commentId, fieldCode, newContent) => {
        const token = localStorage.getItem("token");

        const res = await fetch(`http://localhost:8080/api/comments/${commentId}`, {
            method: "PUT",
            headers: {
                "Content-Type": "application/json",
                Authorization: `Bearer ${token}`
            },
            body: JSON.stringify({ content: newContent })
        });

        if (!res.ok) {
            alert("Edit failed.");
            return;
        }

        setCommentsByField(prev => ({
            ...prev,
            [fieldCode]: prev[fieldCode].map(c =>
                c.id === commentId ? { ...c, content: newContent } : c
            )
        }));
    };

    const submitReply = (fieldCode, parentId) => {
        if (!replyText.trim()) return;

        const token = localStorage.getItem("token");

        fetch("http://localhost:8080/api/comments", {
            method: "POST",
            headers: {
                "Content-Type": "application/json",
                Authorization: `Bearer ${token}`,
            },
            body: JSON.stringify({
                taskId: Number(taskId),
                fieldCode: fieldCode,
                content: replyText,
                parentCommentId: parentId,
            }),
        })
            .then((res) => res.json())
            .then((saved) => {
                setCommentsByField((prev) => ({
                    ...prev,
                    [fieldCode]: [...(prev[fieldCode] || []), saved],
                }));
                setReplyTarget(null);
                setReplyText("");
            })
            .catch((err) => console.error(err));
    };

    const renderCommentThread = (c, fieldCode, depth = 0) => {
        const isMine = c.username === username;
        const isReply = !!c.parentCommentId;

        return (
            <div key={c.id} style={{ marginLeft: depth * 22 }}>
                {/* COMMENT BUBBLE */}
                <div
                    style={{
                        display: "flex",
                        justifyContent: isReply
                            ? "flex-start" // reply HER ZAMAN solda
                            : (isMine ? "flex-end" : "flex-start"),
                        marginBottom: "12px",
                    }}
                >
                    <div
                        style={{
                            maxWidth: "70%",
                            padding: "12px 16px",
                            borderRadius: "14px",
                            background: isMine
                                ? "linear-gradient(135deg, rgba(14,165,233,0.7), rgba(2,132,199,0.7))"
                                : "rgba(255,255,255,0.08)",
                            border: isMine
                                ? "1px solid rgba(14,165,233,0.4)"
                                : "1px solid rgba(255,255,255,0.12)",
                            color: "white",
                            backdropFilter: "blur(6px)",
                            boxShadow: isMine
                                ? "0 4px 12px rgba(14,165,233,0.25)"
                                : "0 4px 12px rgba(0,0,0,0.25)",
                            fontSize: "0.95rem",
                            lineHeight: "1.45",
                            whiteSpace: "pre-wrap",
                            transition: "0.25s",
                        }}
                    >
                        {/* Username + Like + Report */}
                        {!isMine && (
                            <div
                                style={{
                                    fontWeight: "600",
                                    marginBottom: "4px",
                                    opacity: 0.85,
                                    display: "flex",
                                    alignItems: "center",
                                    gap: "8px",
                                }}
                            >
                                {c.username}

                                <button
                                    onClick={() => likeComment(c.id, fieldCode)}
                                    style={{
                                        background: "none",
                                        border: "none",
                                        color: c.userLiked ? "#f87171" : "#aaa",
                                        cursor: "pointer",
                                    }}
                                >
                                    {c.userLiked ? "❤️" : "🤍"} {c.likeCount}
                                </button>

                                {/* Report button */}
                                <button
                                    onClick={() => {
                                        setActiveAction("report");
                                        setReportContext({
                                            targetType: "PARTICIPANT",
                                            artifact: null,
                                            reportedUsername: c.username,
                                        });
                                    }}
                                    style={{
                                        background: "none",
                                        border: "none",
                                        color: "#facc15",
                                        cursor: "pointer",
                                    }}
                                >
                                    ⚠️
                                </button>
                            </div>
                        )}
                        {/* EDIT + DELETE BUTTONS FOR OWNER */}
                        {isMine && !c.deleted && (
                            <div style={{ marginTop: "6px", display: "flex", gap: "10px" }}>
                                <button
                                    onClick={() => {
                                        setEditingCommentId(c.id);
                                        setEditText(c.content);
                                    }}
                                    style={{ color: "#60a5fa", background: "none", border: "none", cursor: "pointer" }}
                                >
                                    Edit
                                </button>

                                <button
                                    onClick={() => deleteComment(c.id, fieldCode)}
                                    style={{ color: "#f87171", background: "none", border: "none", cursor: "pointer" }}
                                >
                                    Delete
                                </button>
                            </div>
                        )}
                        {/* Content */}
                        {/* CONTENT OR EDIT MODE */}
                        {editingCommentId === c.id ? (
                            <div>
        <textarea
            value={editText}
            onChange={(e) => setEditText(e.target.value)}
            style={{
                width: "100%",
                marginTop: "6px",
                padding: "8px",
                borderRadius: "8px",
                background: "rgba(255,255,255,0.08)",
                border: "1px solid rgba(255,255,255,0.2)",
                color: "white"
            }}
        />
                                <button
                                    onClick={() => {
                                        editComment(c.id, fieldCode, editText);
                                        setEditingCommentId(null);
                                    }}
                                    style={{
                                        marginTop: "6px",
                                        background: "rgba(56,189,248,0.35)",
                                        padding: "6px 12px",
                                        borderRadius: "8px",
                                        border: "1px solid rgba(56,189,248,0.6)",
                                        color: "#a5f3fc"
                                    }}
                                >
                                    Save
                                </button>
                                <button
                                    onClick={() => setEditingCommentId(null)}
                                    style={{
                                        marginLeft: "10px",
                                        marginTop: "6px",
                                        background: "rgba(255,255,255,0.1)",
                                        padding: "6px 12px",
                                        borderRadius: "8px",
                                        border: "1px solid rgba(255,255,255,0.2)",
                                        color: "white"
                                    }}
                                >
                                    Cancel
                                </button>
                            </div>
                        ) : (
                            <div style={{ whiteSpace: "pre-wrap" }}>
                                {c.deleted ? "[deleted]" : c.content}
                            </div>
                        )}

                        {/* Footer */}
                        <div
                            style={{
                                fontSize: "0.7rem",
                                opacity: 0.6,
                                marginTop: "6px",
                                textAlign: isMine ? "right" : "left",
                            }}
                        >
                            {new Date(c.createdAt).toLocaleString()}
                        </div>
                        {/* SEE REPLIES */}
                        {c.replies && c.replies.length > 0 && (
                            <button
                                onClick={() =>
                                    setOpenReplies(prev => ({
                                        ...prev,
                                        [c.id]: !prev[c.id]
                                    }))
                                }
                                style={{
                                    background: "none",
                                    border: "none",
                                    color: "#60a5fa",
                                    cursor: "pointer",
                                    fontSize: "0.8rem",
                                    marginTop: "4px"
                                }}
                            >
                                {openReplies[c.id] ? "Hide replies ▲" : `See replies (${c.replies.length}) ▼`}
                            </button>
                        )}
                        {/* REPLY BUTTON */}
                        {!isMine && (
                        <button
                            style={{
                                marginTop: "4px",
                                background: "none",
                                border: "none",
                                color: "#60a5fa",
                                cursor: "pointer",
                                fontSize: "0.8rem",
                            }}
                            onClick={() =>
                                setReplyTarget(c.id === replyTarget ? null : c.id)
                            }
                        >
                            Reply
                        </button>
                        )}

                        {/* REPLY BOX */}
                        {replyTarget === c.id && (
                            <div style={{ marginTop: "6px" }}>
                            <textarea
                                value={replyText}
                                onChange={(e) => setReplyText(e.target.value)}
                                style={{
                                    width: "100%",
                                    padding: "8px",
                                    borderRadius: "6px",
                                    background: "rgba(255,255,255,0.08)",
                                    border: "1px solid rgba(255,255,255,0.2)",
                                    color: "white",
                                }}
                                placeholder="Write a reply..."
                            />

                                <button
                                    onClick={() =>
                                        submitReply(fieldCode, c.id)
                                    }
                                    style={{
                                        marginTop: "6px",
                                        background: "rgba(56,189,248,0.35)",
                                        padding: "6px 12px",
                                        borderRadius: "8px",
                                        border: "1px solid rgba(56,189,248,0.6)",
                                        color: "#a5f3fc",
                                    }}
                                >
                                    Send Reply
                                </button>
                            </div>
                        )}
                    </div>
                </div>

                {/* CHILD COMMENTS */}
                {openReplies[c.id] && c.replies &&
                    c.replies.map(child =>
                        renderCommentThread(child, fieldCode, depth + 1)
                    )}
            </div>
        );
    };

    const submitReport = async () => {
        if (!reportReason.trim() || !reportDescription.trim()) {
            setReportError("Please provide both a reason and a description.");
            setReportSuccess("");
            return;
        }

        if (!reportContext) return;

        setReportSubmitting(true);
        setReportError("");
        setReportSuccess("");

        const token = localStorage.getItem("token");

        try {
            const res = await fetch("http://localhost:8080/api/reports", {
                method: "POST",
                headers: {
                    "Content-Type": "application/json",
                    Authorization: `Bearer ${token}`,
                },
                body: JSON.stringify({
                    taskId: Number(taskId),
                    type: reportContext.targetType, // "ARTIFACT" | "PARTICIPANT"
                    artifactId:
                        reportContext.targetType === "ARTIFACT"
                            ? reportContext.artifact?.id
                            : reportContext.artifact?.id || null,
                    reportedUsername:
                        reportContext.targetType === "PARTICIPANT"
                            ? reportContext.reportedUsername
                            : null,
                    reason: reportReason,
                    description: reportDescription,
                }),
            });

            if (!res.ok) {
                throw new Error("Report failed");
            }

            await res.json(); // istersen ignore

            setReportSuccess("Report submitted. Thank you.");
            setReportError("");

            // İstersen bir süre sonra modal’ı kapat
            setTimeout(() => {
                setActiveAction(null);
                setReportContext(null);
                setReportReason("");
                setReportDescription("");
                setReportSuccess("");
            }, 800);
        } catch (e) {
            console.error(e);
            setReportError("An error occurred while submitting the report.");
            setReportSuccess("");
        } finally {
            setReportSubmitting(false);
        }
    };

    //RATING EVALUATION
    function ModernRating({ value, onChange }) {
        const [hoverValue, setHoverValue] = React.useState(null);

        return (
            <div style={{ display: "flex", gap: 14, marginTop: 10 }}>
                {[1,2,3,4,5].map((n) => {

                    // ⭐ SADECE seçilen yıldızlar sarı olacak
                    const isFilled = n <= value;

                    // ⭐ Hover sadece büyütür, glow verir
                    const isHovered = hoverValue === n;

                    return (
                        <div
                            key={n}
                            onMouseEnter={() => setHoverValue(n)}
                            onMouseLeave={() => setHoverValue(null)}
                            onClick={() => onChange(n)}
                        >
                            <AnimatedFillStar
                                id={n}
                                filled={isFilled}        // ⭐ sadece seçili yıldızlar dolu
                                hovered={isHovered}      // ⭐ hover efekti
                                animate={n === value}    // ⭐ animasyon sadece seçilen yıldızda
                            />
                        </div>
                    );
                })}
            </div>
        );
    }

    function AnimatedFillStar({ filled, hovered, animate, id }) {
        const size = 32;
        const clipId = `clip-${id}`;

        return (
            <svg
                width={size}
                height={size}
                viewBox="0 0 24 24"
                style={{
                    cursor: "pointer",
                    justifyContent: "center",
                    alignItems: "center",
                    transition: "transform .25s ease",
                    transform: hovered ? "scale(1.22)" : "scale(1)",
                    filter: filled
                        ? "drop-shadow(0 0 10px rgba(255, 215, 0, 0.8))"
                        : "none",
                }}
            >
                {/* Only animate if this star is selected */}
                <clipPath id={clipId}>
                    <rect
                        x="0"
                        y="0"
                        width={filled ? 24 : 0}
                        height="24"
                    >
                        {animate && (
                            <animate
                                attributeName="width"
                                from="0"
                                to="24"
                                dur="0.35s"
                                fill="freeze"
                            />
                        )}
                    </rect>
                </clipPath>

                {/* Outline */}
                <path
                    d="M12 2l3.09 6.26L22 9.27l-5 4.87L18.18 22 12 18.56 5.82 22 7 14.14l-5-4.87 6.91-1.01L12 2z"
                    fill="none"
