    function renderCriterionInput(crit) {
        const value = answers[crit.id] || "";

        switch (crit.type) {

            /* ------------------ RATING ------------------ */
            case "RATING":
                return (
                    <div style={{ width: "100%", display: "flex", justifyContent: "center" }}>
                    <ModernRating
                        value={Number(value) || 0}
                        onChange={(v) =>
                            setAnswers({ ...answers, [crit.id]: v })
                        }
                    />
                    </div>
                );
            /* ------------------ MULTIPLE CHOICE ------------------ */
            case "MULTIPLE_CHOICE":
                return (
                    <div style={styles.choiceGrid}>
                        {crit.options.map((opt, i) => {
                            const selected = crit.multipleSelection
                                ? (value ? value.split(",") : []).includes(opt)
                                : value === opt;

                            return (
                                <div
                                    key={i}
                                    style={{
                                        ...styles.choiceCard,
                                        ...(selected ? styles.choiceCardSelected : {}),
                                    }}
                                    onClick={() => {
                                        if (!crit.multipleSelection) {
                                            setAnswers({ ...answers, [crit.id]: opt });
                                        } else {
                                            let setVal = new Set(value ? value.split(",") : []);
                                            if (setVal.has(opt)) setVal.delete(opt);
                                            else setVal.add(opt);
                                            setAnswers({
                                                ...answers,
                                                [crit.id]: Array.from(setVal).join(","),
                                            });
                                        }
                                    }}
                                >
                                    <span style={styles.choiceText}>{opt}</span>
                                </div>
                            );
                        })}
                    </div>
                );
            /* ------------------ OPEN ENDED TEXT ------------------ */
            case "OPEN_ENDED":
                return (
                    <textarea
                        style={{ width: "100%", minHeight: 80 }}
                        value={value}
                        onChange={e =>
                            setAnswers({ ...answers, [crit.id]: e.target.value })
                        }
                    />
                );
            /* ------------------ NUMERIC ------------------ */
            case "NUMERIC":
                return (
                    <input
                        type="number"
                        min={crit.minValue}
                        max={crit.maxValue}
                        step={crit.integerOnly ? 1 : "any"}
                        value={value}
                        onChange={e =>
                            setAnswers({ ...answers, [crit.id]: e.target.value })
                        }
                        style={{ width: "120px" }}
                    />
                );

            /* ------------------ CODE EDIT ------------------ */
            case "CODE_EDIT":
                return (
                    <textarea
                        style={{ width: "100%", minHeight: 120, fontFamily: "monospace" }}
                        value={value}
                        onChange={e =>
                            setAnswers({ ...answers, [crit.id]: e.target.value })
                        }
                    />
                );

            /* ------------------ IMAGE HIGHLIGHT ------------------ */
            case "IMAGE_HIGHLIGHT":
                return (
                    <div>
                        <input
                            type="text"
                            placeholder="annotation coordinates (e.g. x1,y1;x2,y2)"
                            value={value}
                            onChange={e =>
                                setAnswers({ ...answers, [crit.id]: e.target.value })
                            }
                            style={{ width: "100%" }}
                        />
                    </div>
                );

            default:
                return <div>Unsupported criterion type</div>;
        }
    }

